const body = $input.first().json.body;
const rawMessage = body.data.message?.conversation || '';
const sender = body.data.key?.remoteJid || '';
const senderName = body.data.pushName || 'User';
const instanceName = body.instance || 'pricebot';
const messageId = body.data.key?.id || '';
const timestamp = body.data.messageTimestamp || Date.now();

// Dedup: ignore messages older than 60 seconds
const msgAge = Date.now() / 1000 - timestamp;
if (msgAge > 30) {
  return [];
}

// Ignore messages sent BY the bot itself (fromMe)
const fromMe = body.data.key?.fromMe || false;
if (fromMe) {
  return [];
}

// Sanitize message to prevent JSON breaking
const message = rawMessage
  .replace(/\r\n/g, ', ')
  .replace(/\n/g, ', ')
  .replace(/\r/g, ', ')
  .replace(/"/g, "'")
  .replace(/\\/g, '')
  .trim();

return [{ json: { message, sender, senderName, instanceName, messageId, timestamp } }];

