const raw = $input.first().json.choices?.[0]?.message?.content || $input.first().json.response || '';
const sender = $('Extract Message Details').first().json.sender;
const instanceName = $('Extract Message Details').first().json.instanceName;

let groceryItems = [];
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  const match = cleaned.match(/\[.*\]/s);
  groceryItems = match ? JSON.parse(match[0]) : [];
} catch(e) { groceryItems = []; }

if (!groceryItems.length) {
  return [{ json: { isError: true, sender, instanceName } }];
}

return [{ json: { isError: false, groceryItems, sender, instanceName } }];

const allInputs = $input.all().map(i => i.json);

const blinkitRaw = allInputs.filter(i => i.product_name !== undefined);
const zeptoRaw = allInputs.filter(i => i.selling_price !== undefined);

const sender = $('Extract Message Details').first().json.sender;
const instanceName = $('Extract Message Details').first().json.instanceName;
const groceryItems = $('Temp node 2').first().json.groceryItems;

function parseQuantityInGrams(unit) {
  if (!unit) return null;
  const u = unit.toLowerCase();
  const num = parseFloat(u);
  if (isNaN(num)) return null;
  if (u.includes('kg')) return num * 1000;
  if (u.includes('g')) return num;
  if (u.includes('litre') || u.includes('ltr') || u.includes('l')) return num * 1000;
  if (u.includes('ml')) return num;
  return num;
}

function unitsNeeded(requestedQty, requestedUnit, productUnit) {
  const requested = parseQuantityInGrams(`${requestedQty}${requestedUnit}`);
  const packSize = parseQuantityInGrams(productUnit);
  if (!requested || !packSize) return 1;
  return Math.ceil(requested / packSize);
}

function bestBlinkit(arr, itemName) {
  try {
    if (!Array.isArray(arr) || !arr.length) return null;
    const name = itemName.toLowerCase();
    const words = name.split(' ').filter(w => w.length > 2);
    const itemResults = arr.filter(p => (p.search_query || '').toLowerCase() === name);
    const pool = itemResults.length > 0 ? itemResults : arr;
    const scored = pool.map(p => {
      const pname = (p.product_name || '').toLowerCase();
      const price = parseFloat(p.price || 0);
      if (price <= 0) return null;
      const exactMatch = pname.includes(name) ? 3 : 0;
      const wordMatches = words.filter(w => pname.includes(w)).length;
      return { p, price, score: exactMatch + wordMatches };
    }).filter(Boolean);
    if (!scored.length) return null;
    scored.sort((a, b) => b.score - a.score || a.price - b.price);
    const best = scored[0].p;
    return {
      productName: best.product_name || itemName,
      price: parseFloat(best.price || 0),
      mrp: parseFloat(best.original_price || 0),
      unit: best.unit || '',
      inStock: best.availability === 'In Stock'
    };
  } catch(e) { return null; }
}

function bestZepto(arr, itemName) {
  try {
    if (!Array.isArray(arr) || !arr.length) return null;
    const name = itemName.toLowerCase();
    const words = name.split(' ').filter(w => w.length > 2);
    const itemResults = arr.filter(p => (p.search_query || '').toLowerCase() === name);
    const pool = itemResults.length > 0 ? itemResults : arr;
    const scored = pool.map(p => {
      const pname = (p.name || '').toLowerCase();
      const price = parseFloat(p.selling_price || 0);
      if (price <= 0) return null;
      const exactMatch = pname.includes(name) ? 3 : 0;
      const wordMatches = words.filter(w => pname.includes(w)).length;
      return { p, price, score: exactMatch + wordMatches };
    }).filter(Boolean);
    if (!scored.length) return null;
    scored.sort((a, b) => b.score - a.score || a.price - b.price);
    const best = scored[0].p;
    return {
      productName: best.name || itemName,
      price: parseFloat(best.selling_price || 0),
      mrp: parseFloat(best.mrp || 0),
      unit: best.formatted_packsize || '',
      inStock: best.out_of_stock === false
    };
  } catch(e) { return null; }
}

const results = groceryItems.map(item => {
  const blinkit = bestBlinkit(blinkitRaw, item.name);
  const zepto = bestZepto(zeptoRaw, item.name);

  // Calculate units needed and effective price for each platform
  if (blinkit) {
    const qty = unitsNeeded(item.quantity, item.unit, blinkit.unit);
    blinkit.unitsNeeded = qty;
    blinkit.effectivePrice = Math.round(blinkit.price * qty * 100) / 100;
    blinkit.effectiveMrp = Math.round(blinkit.mrp * qty * 100) / 100;
  }
  if (zepto) {
    const qty = unitsNeeded(item.quantity, item.unit, zepto.unit);
    zepto.unitsNeeded = qty;
    zepto.effectivePrice = Math.round(zepto.price * qty * 100) / 100;
    zepto.effectiveMrp = Math.round(zepto.mrp * qty * 100) / 100;
  }

  return { json: { item, blinkit, zepto, sender, instanceName } };
});

return results;

const aggregated = $input.first().json;
const results = aggregated.data || [];

const sender = results[0]?.sender || $('Extract Message Details').first().json.sender;
const instanceName = results[0]?.instanceName || 'pricebot';

let msg = `🛒 *Grocery Price Comparison*\n`;
msg += `📍 Bandra West, Mumbai (400050)\n`;
msg += `━━━━━━━━━━━━━━━━━━━━\n\n`;

let blinkitTotal = 0, zeptoTotal = 0;
let blinkitCount = 0, zeptoCount = 0;
const total = results.length;

for (const r of results) {
  const item = r.item;
  const blinkit = r.blinkit;
  const zepto = r.zepto;

  if (!item) continue;

  const label = `${item.quantity} ${item.unit} ${item.name.charAt(0).toUpperCase() + item.name.slice(1)}`;
  msg += `*${label}*\n`;

  const bp = blinkit?.effectivePrice || blinkit?.price || 0;
  const zp = zepto?.effectivePrice || zepto?.price || 0;
  const bestIsB = bp > 0 && (zp === 0 || bp <= zp);
  const bestIsZ = zp > 0 && (bp === 0 || zp < bp);

  if (blinkit && bp > 0) {
    const crown = bestIsB ? ' 🏆' : '';
    const effMrp = blinkit.effectiveMrp || blinkit.mrp || 0;
    const strike = effMrp > bp ? ` ~~₹${effMrp}~~` : '';
    const packInfo = blinkit.unitsNeeded > 1
      ? ` _(${blinkit.unitsNeeded}x ${blinkit.unit})_`
      : ` _(${blinkit.unit})_`;
    msg += `  🟡 Blinkit: ₹${bp}${strike}${packInfo}${crown}\n`;
    blinkitTotal += bp; blinkitCount++;
  } else {
    msg += `  🟡 Blinkit: ❌ Not found\n`;
  }

  if (zepto && zp > 0) {
    const crown = bestIsZ ? ' 🏆' : '';
    const effMrp = zepto.effectiveMrp || zepto.mrp || 0;
    const strike = effMrp > zp ? ` ~~₹${effMrp}~~` : '';
    const packInfo = zepto.unitsNeeded > 1
      ? ` _(${zepto.unitsNeeded}x ${zepto.unit})_`
      : ` _(${zepto.unit})_`;
    msg += `  🔴 Zepto: ₹${zp}${strike}${packInfo}${crown}\n`;
    zeptoTotal += zp; zeptoCount++;
  } else {
    msg += `  🔴 Zepto: ❌ Not found\n`;
  }
  msg += `\n`;
}

msg += `━━━━━━━━━━━━━━━━━━━━\n`;
msg += `💰 *Basket Total*\n`;
if (blinkitCount > 0) msg += `  🟡 Blinkit: ₹${blinkitTotal.toFixed(0)} (${blinkitCount}/${total} items)\n`;
if (zeptoCount > 0) msg += `  🔴 Zepto: ₹${zeptoTotal.toFixed(0)} (${zeptoCount}/${total} items)\n`;

if (blinkitTotal > 0 && zeptoTotal > 0) {
  const diff = Math.abs(blinkitTotal - zeptoTotal).toFixed(0);
  const cheaper = blinkitTotal <= zeptoTotal ? '🟡 Blinkit' : '🔴 Zepto';
  msg += `\n💡 *${cheaper} saves you ₹${diff} on this list!*\n`;
}

msg += `\n🏆 = Best price per item\n`;
msg += `⏰ ${new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })}\n`;
msg += `_Prices vary by availability. Verify before ordering._`;

return [{ json: { formattedMessage: msg, sender, instanceName } }];

